import Ajv from 'ajv'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import type { OVDocument } from './types'

export class OVValidationError extends Error {
  constructor(public errors: any[]) {
    super('OV document validation failed')
    this.name = 'OVValidationError'
  }
}

let validator: any = null

export function validateOV(doc: unknown, schemaPath?: string): asserts doc is OVDocument {
  if (!validator) {
    const ajv = new Ajv({ allErrors: true })
    const path = schemaPath || join(__dirname, '../schema/ov.schema.json')
    const schema = JSON.parse(readFileSync(path, 'utf8'))
    validator = ajv.compile(schema)
  }

  const valid = validator(doc)
  if (!valid) {
    throw new OVValidationError(validator.errors || [])
  }
}
