import type { ExecuteRequest, Actor, Context } from '@openverb/runtime'
import type { OVDocument } from './types'
import { resolveVariables } from './variables'

export function bridgeToRuntime(
  doc: OVDocument,
  inputs: Record<string, any>,
  actor?: Actor,
  context?: Context
): ExecuteRequest[] {
  const defaultActor: Actor = actor || { type: 'user', id: 'local' }
  const defaultContext: Context = context || {}

  // Fill default inputs
  const resolvedInputs = { ...inputs }
  if (doc.inputs) {
    for (const [key, def] of Object.entries(doc.inputs)) {
      if (resolvedInputs[key] === undefined && def.default !== undefined) {
        resolvedInputs[key] = def.default
      }
    }
  }

  return doc.actions.map(action => ({
    verbId: action.verb,
    args: resolveVariables(action.params || {}, resolvedInputs),
    actor: defaultActor,
    context: defaultContext
  }))
}
