import * as yaml from 'yaml'
import type { OVDocument } from './types'

export function parseOV(content: string): OVDocument {
  // If it starts with {, parse as JSON, else parse as YAML
  if (content.trimStart().startsWith('{')) {
    return JSON.parse(content) as OVDocument
  }
  return yaml.parse(content) as OVDocument
}
