export function resolveVariables(params: Record<string, any>, inputs: Record<string, any>, context: Record<string, any> = {}): Record<string, any> {
  const vars = { inputs, ...context }

  function resolveString(str: string): any {
    // Exact match for full variable replacement
    const exactMatch = str.match(/^\$\{([^}]+)\}$/)
    if (exactMatch) {
      const path = exactMatch[1].split('.')
      let val: any = vars
      for (const p of path) {
        val = val?.[p]
      }
      return val
    }

    // String interpolation
    return str.replace(/\$\{([^}]+)\}/g, (match, pathStr) => {
      const path = pathStr.split('.')
      let val: any = vars
      for (const p of path) {
        val = val?.[p]
      }
      return val !== undefined ? String(val) : match
    })
  }

  function walk(obj: any): any {
    if (typeof obj === 'string') return resolveString(obj)
    if (Array.isArray(obj)) return obj.map(walk)
    if (obj !== null && typeof obj === 'object') {
      const newObj: any = {}
      for (const [k, v] of Object.entries(obj)) {
        newObj[k] = walk(v)
      }
      return newObj
    }
    return obj
  }

  return walk(params)
}
